CREATE TABLE enterprise_directory_connectors(id TEXT NOT NULL,tenant_id TEXT NOT NULL REFERENCES tenants(id),environment TEXT NOT NULL,app_env TEXT NOT NULL,name TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('scim','synthetic_directory')),owner_id TEXT NOT NULL REFERENCES users(id),config_hash TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 1000000000),updated_at TEXT NOT NULL,PRIMARY KEY(tenant_id,environment,app_env,id));
CREATE TABLE enterprise_directory_users(id TEXT PRIMARY KEY REFERENCES users(id),tenant_id TEXT NOT NULL,environment TEXT NOT NULL,app_env TEXT NOT NULL,connector_id TEXT NOT NULL,user_name TEXT NOT NULL,name_key TEXT NOT NULL,external_id TEXT,display_name TEXT NOT NULL,display_key TEXT NOT NULL,profile_json TEXT NOT NULL CHECK(json_valid(profile_json)),active INTEGER NOT NULL CHECK(active IN(0,1)),deleted INTEGER NOT NULL CHECK(deleted IN(0,1)),review_required INTEGER NOT NULL CHECK(review_required IN(0,1)),directory_version INTEGER NOT NULL,control_version INTEGER NOT NULL,policy_hash TEXT NOT NULL,version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 1000000000),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(tenant_id,environment,app_env,connector_id) REFERENCES enterprise_directory_connectors(tenant_id,environment,app_env,id),UNIQUE(tenant_id,environment,app_env,connector_id,id));
CREATE UNIQUE INDEX enterprise_directory_user_name ON enterprise_directory_users(tenant_id,environment,app_env,connector_id,name_key) WHERE deleted=0;
CREATE INDEX enterprise_directory_user_external ON enterprise_directory_users(tenant_id,environment,app_env,connector_id,external_id);
CREATE TABLE enterprise_directory_groups(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,environment TEXT NOT NULL,app_env TEXT NOT NULL,connector_id TEXT NOT NULL,external_id TEXT,display_name TEXT NOT NULL,display_key TEXT NOT NULL,deleted INTEGER NOT NULL CHECK(deleted IN(0,1)),version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 1000000000),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(tenant_id,environment,app_env,connector_id) REFERENCES enterprise_directory_connectors(tenant_id,environment,app_env,id),UNIQUE(tenant_id,environment,app_env,connector_id,id));
CREATE TABLE enterprise_directory_group_members(tenant_id TEXT NOT NULL,environment TEXT NOT NULL,app_env TEXT NOT NULL,connector_id TEXT NOT NULL,group_id TEXT NOT NULL,user_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(group_id,user_id),FOREIGN KEY(tenant_id,environment,app_env,connector_id,group_id) REFERENCES enterprise_directory_groups(tenant_id,environment,app_env,connector_id,id),FOREIGN KEY(tenant_id,environment,app_env,connector_id,user_id) REFERENCES enterprise_directory_users(tenant_id,environment,app_env,connector_id,id));
CREATE TABLE enterprise_directory_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,environment TEXT NOT NULL,app_env TEXT NOT NULL,connector_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,resource_id TEXT NOT NULL,revision INTEGER NOT NULL,member_event_id TEXT,created_at TEXT NOT NULL);
CREATE INDEX enterprise_directory_event_scope ON enterprise_directory_events(tenant_id,environment,app_env,connector_id,created_at,id);
CREATE TRIGGER enterprise_directory_events_immutable_update BEFORE UPDATE ON enterprise_directory_events BEGIN SELECT RAISE(ABORT,'Directory events are append only');END;
CREATE TRIGGER enterprise_directory_events_immutable_delete BEFORE DELETE ON enterprise_directory_events BEGIN SELECT RAISE(ABORT,'Directory events are append only');END;
